            char next = input.charAt(i + 1);
            result.append(next);
            i++; // Skip the escaped character
        } else if (c == '\\' && i + 1 >= input.length()) {
            // Trailing backslash; keep it
            result.append(c);
        } else {
            result.append(c);
        }
    }
    return result.toString();
}

